pub open spec fn range_block_ids(lo: nat, hi: nat, page_id: PageId, block_size: nat) -> Set<BlockId> {
    vstd::contrib::set_build!{
        BlockId {
            page_id,
            idx,
            slice_idx: BlockId::get_slice_idx(page_id, idx, block_size),
            block_size,
        }: BlockId |
        idx: nat in lo..hi,
    }
}

