    #[inductive(reserve_uniq_identifier)]
    fn reserve_uniq_identifier_inductive(pre: Self, post: Self) {
        lemma_heap_get_unused_uniq_field(pre.heap_shared_access.dom() + pre.reserved_uniq);
        assert(pre.inv_reserved2());
        assert(post.heap_shared_access.dom() =~= pre.heap_shared_access.dom());
        assert(post.reserved_uniq =~= pre.reserved_uniq.insert(
            HeapId { id: 0, uniq: heap_get_unused_uniq_field(pre.heap_shared_access.dom() + pre.reserved_uniq), provenance: Provenance::null() }));
        assert forall |hid1: HeapId, hid2: HeapId|
            post.reserved_uniq.contains(hid1)
            && post.heap_shared_access.dom().contains(hid2)
            ==> hid1.uniq != hid2.uniq
        by {
            if post.reserved_uniq.contains(hid1) && post.heap_shared_access.dom().contains(hid2) {
                assert(pre.reserved_uniq.contains(hid1)
                    || hid1 == (HeapId { id: 0, uniq: heap_get_unused_uniq_field(pre.heap_shared_access.dom() + pre.reserved_uniq), provenance: Provenance::null() }));
            if pre.reserved_uniq.contains(hid1) {
                assert(pre.inv_reserved2());
                assert(hid1.uniq != hid2.uniq);
            } else {
                assert(hid1 == (HeapId { id: 0, uniq: heap_get_unused_uniq_field(pre.heap_shared_access.dom() + pre.reserved_uniq), provenance: Provenance::null() }));
                assert((pre.heap_shared_access.dom() + pre.reserved_uniq).contains(hid2));
                assert(hid2.uniq != heap_get_unused_uniq_field(pre.heap_shared_access.dom() + pre.reserved_uniq));
                assert(hid1.uniq != hid2.uniq);
            }
        }
    }


}}

